=head2 Google::Cloud::Deploy::V1::CloudDeploy::Target

A `Target` resource in the Cloud Deploy API.

A `Target` defines a location to which a Skaffold configuration
can be deployed.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Identifier. Name of the `Target`. Format is
`projects/{project}/locations/{location}/targets/{target}`.
The `target` component must match `[a-z]([a-z0-9-]{0,61}[a-z0-9])?`

=item * C<< $msg->target_id() >> / C<< $msg->target_id($value) >>

Type: C<String>

Output only. Resource id of the `Target`.

=item * C<< $msg->uid() >> / C<< $msg->uid($value) >>

Type: C<String>

Output only. Unique identifier of the `Target`.

=item * C<< $msg->description() >> / C<< $msg->description($value) >>

Type: C<String>

Optional. Description of the `Target`. Max length is 255 characters.

=item * C<< $msg->annotations() >> / C<< $msg->annotations($value) >>

Type: C<Message> (L<Google::Cloud::Deploy::V1::CloudDeploy::Target::AnnotationsEntry>)

Optional. User annotations. These attributes can only be set and used by
the user, and not by Cloud Deploy. See
https://google.aip.dev/128#annotations for more details such as format and
size limitations.

=item * C<< $msg->labels() >> / C<< $msg->labels($value) >>

Type: C<Message> (L<Google::Cloud::Deploy::V1::CloudDeploy::Target::LabelsEntry>)

Optional. Labels are attributes that can be set and used by both the
user and by Cloud Deploy. Labels must meet the following constraints:

* Keys and values can contain only lowercase letters, numeric characters,
underscores, and dashes.
* All characters must use UTF-8 encoding, and international characters are
allowed.
* Keys must start with a lowercase letter or international character.
* Each resource is limited to a maximum of 64 labels.

Both keys and values are additionally constrained to be <= 128 bytes.

=item * C<< $msg->require_approval() >> / C<< $msg->require_approval($value) >>

Type: C<Bool>

Optional. Whether or not the `Target` requires approval.

=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Time at which the `Target` was created.

=item * C<< $msg->update_time() >> / C<< $msg->update_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Most recent time at which the `Target` was updated.

=item * C<< $msg->gke() >> / C<< $msg->gke($value) >>

Type: C<Message> (L<Google::Cloud::Deploy::V1::CloudDeploy::GkeCluster>)

Optional. Information specifying a GKE Cluster.

=item * C<< $msg->anthos_cluster() >> / C<< $msg->anthos_cluster($value) >>

Type: C<Message> (L<Google::Cloud::Deploy::V1::CloudDeploy::AnthosCluster>)

Optional. Information specifying an Anthos Cluster.

=item * C<< $msg->run() >> / C<< $msg->run($value) >>

Type: C<Message> (L<Google::Cloud::Deploy::V1::CloudDeploy::CloudRunLocation>)

Optional. Information specifying a Cloud Run deployment target.

=item * C<< $msg->multi_target() >> / C<< $msg->multi_target($value) >>

Type: C<Message> (L<Google::Cloud::Deploy::V1::CloudDeploy::MultiTarget>)

Optional. Information specifying a multiTarget.

=item * C<< $msg->custom_target() >> / C<< $msg->custom_target($value) >>

Type: C<Message> (L<Google::Cloud::Deploy::V1::CloudDeploy::CustomTarget>)

Optional. Information specifying a Custom Target.

=item * C<< $msg->associated_entities() >> / C<< $msg->associated_entities($value) >>

Type: C<Message> (L<Google::Cloud::Deploy::V1::CloudDeploy::Target::AssociatedEntitiesEntry>)

Optional. Map of entity IDs to their associated entities. Associated
entities allows specifying places other than the deployment target for
specific features. For example, the Gateway API canary can be configured to
deploy the HTTPRoute to a different cluster(s) than the deployment cluster
using associated entities. An entity ID must consist of lower-case letters,
numbers, and hyphens, start with a letter and end with a letter or a
number, and have a max length of 63 characters. In other words, it must
match the following regex: `^[a-z]([a-z0-9-]{0,61}[a-z0-9])?$`.

=item * C<< $msg->etag() >> / C<< $msg->etag($value) >>

Type: C<String>

Optional. This checksum is computed by the server based on the value of
other fields, and may be sent on update and delete requests to ensure the
client has an up-to-date value before proceeding.

=item * C<< $msg->execution_configs() >> / C<< $msg->execution_configs($value) >>

Type: C<Message> (L<Google::Cloud::Deploy::V1::CloudDeploy::ExecutionConfig>)

Optional. Configurations for all execution that relates to this `Target`.
Each `ExecutionEnvironmentUsage` value may only be used in a single
configuration; using the same value multiple times is an error.
When one or more configurations are specified, they must include the
`RENDER` and `DEPLOY` `ExecutionEnvironmentUsage` values.
When no configurations are specified, execution will use the default
specified in `DefaultPool`.

=item * C<< $msg->deploy_parameters() >> / C<< $msg->deploy_parameters($value) >>

Type: C<Message> (L<Google::Cloud::Deploy::V1::CloudDeploy::Target::DeployParametersEntry>)

Optional. The deploy parameters to use for this target.

