=head2 Google::Cloud::Deploy::V1::CloudDeploy::ExecutionConfig

Configuration of the environment to use when calling Skaffold.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->usages() >> / C<< $msg->usages($value) >>

Type: C<Enum> (L<Google::Cloud::Deploy::V1::ExecutionConfig::ExecutionEnvironmentUsage>)

