=item * C<< $msg->default_pool() >> / C<< $msg->default_pool($value) >>

Type: C<Message> (L<Google::Cloud::Deploy::V1::CloudDeploy::DefaultPool>)

Optional. Use default Cloud Build pool.

=item * C<< $msg->private_pool() >> / C<< $msg->private_pool($value) >>

Type: C<Message> (L<Google::Cloud::Deploy::V1::CloudDeploy::PrivatePool>)

Optional. Use private Cloud Build pool.

=item * C<< $msg->worker_pool() >> / C<< $msg->worker_pool($value) >>

Type: C<String>

Optional. The resource name of the `WorkerPool`, with the format
`projects/{project}/locations/{location}/workerPools/{worker_pool}`.
If this optional field is unspecified, the default Cloud Build pool will be
used.

=item * C<< $msg->service_account() >> / C<< $msg->service_account($value) >>

Type: C<String>

Optional. Google service account to use for execution. If unspecified,
the project execution service account
(<PROJECT_NUMBER>-compute@developer.gserviceaccount.com) is used.

=item * C<< $msg->artifact_storage() >> / C<< $msg->artifact_storage($value) >>

Type: C<String>

Optional. Cloud Storage location in which to store execution outputs. This
can either be a bucket ("gs://my-bucket") or a path within a bucket
("gs://my-bucket/my-dir").
If unspecified, a default bucket located in the same region will be used.

=item * C<< $msg->execution_timeout() >> / C<< $msg->execution_timeout($value) >>

Type: C<Message> (L<Google::Protobuf::Duration::Duration>)

Optional. Execution timeout for a Cloud Build Execution. This must be
between 10m and 24h in seconds format. If unspecified, a default timeout of
1h is used.

=item * C<< $msg->verbose() >> / C<< $msg->verbose($value) >>

Type: C<Bool>

Optional. If true, additional logging will be enabled when running builds
in this execution environment.

=back

