=head2 Google::Cloud::Deploy::V1::CloudDeploy::Rollout

A `Rollout` resource in the Cloud Deploy API.

A `Rollout` contains information around a specific deployment to a `Target`.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Identifier. Name of the `Rollout`. Format is
`projects/{project}/locations/{location}/deliveryPipelines/{deliveryPipeline}/releases/{release}/rollouts/{rollout}`.
The `rollout` component must match `[a-z]([a-z0-9-]{0,61}[a-z0-9])?`

=item * C<< $msg->uid() >> / C<< $msg->uid($value) >>

Type: C<String>

Output only. Unique identifier of the `Rollout`.

=item * C<< $msg->description() >> / C<< $msg->description($value) >>

Type: C<String>

Optional. Description of the `Rollout` for user purposes. Max length is 255
characters.

=item * C<< $msg->annotations() >> / C<< $msg->annotations($value) >>

Type: C<Message> (L<Google::Cloud::Deploy::V1::CloudDeploy::Rollout::AnnotationsEntry>)

Optional. User annotations. These attributes can only be set and used by
the user, and not by Cloud Deploy. See
https://google.aip.dev/128#annotations for more details such as format and
size limitations.

=item * C<< $msg->labels() >> / C<< $msg->labels($value) >>

Type: C<Message> (L<Google::Cloud::Deploy::V1::CloudDeploy::Rollout::LabelsEntry>)

Labels are attributes that can be set and used by both the
user and by Cloud Deploy. Labels must meet the following constraints:

* Keys and values can contain only lowercase letters, numeric characters,
underscores, and dashes.
* All characters must use UTF-8 encoding, and international characters are
allowed.
* Keys must start with a lowercase letter or international character.
* Each resource is limited to a maximum of 64 labels.

Both keys and values are additionally constrained to be <= 128 bytes.

=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Time at which the `Rollout` was created.

=item * C<< $msg->approve_time() >> / C<< $msg->approve_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Time at which the `Rollout` was approved.

=item * C<< $msg->enqueue_time() >> / C<< $msg->enqueue_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Time at which the `Rollout` was enqueued.

=item * C<< $msg->deploy_start_time() >> / C<< $msg->deploy_start_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Time at which the `Rollout` started deploying.

=item * C<< $msg->deploy_end_time() >> / C<< $msg->deploy_end_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Time at which the `Rollout` finished deploying.

=item * C<< $msg->target_id() >> / C<< $msg->target_id($value) >>

Type: C<String>

Required. The ID of Target to which this `Rollout` is deploying.

=item * C<< $msg->approval_state() >> / C<< $msg->approval_state($value) >>

Type: C<Enum> (L<Google::Cloud::Deploy::V1::Rollout::ApprovalState>)

Output only. Approval state of the `Rollout`.

=item * C<< $msg->state() >> / C<< $msg->state($value) >>

Type: C<Enum> (L<Google::Cloud::Deploy::V1::Rollout::State>)

Output only. Current state of the `Rollout`.

=item * C<< $msg->failure_reason() >> / C<< $msg->failure_reason($value) >>

Type: C<String>

Output only. Additional information about the rollout failure, if
available.

=item * C<< $msg->deploying_build() >> / C<< $msg->deploying_build($value) >>

Type: C<String>

Output only. The resource name of the Cloud Build `Build` object that is
used to deploy the Rollout. Format is
`projects/{project}/locations/{location}/builds/{build}`.

=item * C<< $msg->etag() >> / C<< $msg->etag($value) >>

Type: C<String>

This checksum is computed by the server based on the value of other
fields, and may be sent on update and delete requests to ensure the
client has an up-to-date value before proceeding.

=item * C<< $msg->deploy_failure_cause() >> / C<< $msg->deploy_failure_cause($value) >>

Type: C<Enum> (L<Google::Cloud::Deploy::V1::Rollout::FailureCause>)

Output only. The reason this rollout failed. This will always be
unspecified while the rollout is in progress.

=item * C<< $msg->phases() >> / C<< $msg->phases($value) >>

Type: C<Message> (L<Google::Cloud::Deploy::V1::CloudDeploy::Phase>)

Output only. The phases that represent the workflows of this `Rollout`.

=item * C<< $msg->metadata() >> / C<< $msg->metadata($value) >>

Type: C<Message> (L<Google::Cloud::Deploy::V1::CloudDeploy::Metadata>)

Output only. Metadata contains information about the rollout.

=item * C<< $msg->controller_rollout() >> / C<< $msg->controller_rollout($value) >>

Type: C<String>

Output only. Name of the `ControllerRollout`. Format is
`projects/{project}/locations/{location}/deliveryPipelines/{deliveryPipeline}/releases/{release}/rollouts/{rollout}`.

=item * C<< $msg->rollback_of_rollout() >> / C<< $msg->rollback_of_rollout($value) >>

Type: C<String>

Output only. Name of the `Rollout` that is rolled back by this `Rollout`.
Empty if this `Rollout` wasn't created as a rollback.

=item * C<< $msg->rolled_back_by_rollouts() >> / C<< $msg->rolled_back_by_rollouts($value) >>

Type: C<String>

Output only. Names of `Rollouts` that rolled back this `Rollout`.

=item * C<< $msg->active_repair_automation_run() >> / C<< $msg->active_repair_automation_run($value) >>

Type: C<String>

