=head2 Google::Cloud::Deploy::V1::CloudDeploy::CreateRolloutRequest

CreateRolloutRequest is the request object used by `CreateRollout`.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->parent() >> / C<< $msg->parent($value) >>

Type: C<String>

Required. The parent collection in which the `Rollout` must be created.
The format is
`projects/{project_id}/locations/{location_name}/deliveryPipelines/{pipeline_name}/releases/{release_name}`.

=item * C<< $msg->rollout_id() >> / C<< $msg->rollout_id($value) >>

Type: C<String>

Required. ID of the `Rollout`.

=item * C<< $msg->rollout() >> / C<< $msg->rollout($value) >>

Type: C<Message> (L<Google::Cloud::Deploy::V1::CloudDeploy::Rollout>)

Required. The `Rollout` to create.

=item * C<< $msg->request_id() >> / C<< $msg->request_id($value) >>

Type: C<String>

Optional. A request ID to identify requests. Specify a unique request ID
so that if you must retry your request, the server knows to ignore the
request if it has already been completed. The server guarantees that for
at least 60 minutes after the first request.

For example, consider a situation where you make an initial request and the
request times out. If you make the request again with the same request ID,
the server can check if original operation with the same request ID was
received, and if so, will ignore the second request. This prevents clients
from accidentally creating duplicate commitments.

The request ID must be a valid UUID with the exception that zero UUID is
not supported (00000000-0000-0000-0000-000000000000).

=item * C<< $msg->validate_only() >> / C<< $msg->validate_only($value) >>

Type: C<Bool>

Optional. If set to true, the request is validated and the user is provided
with an expected result, but no actual change is made.

=item * C<< $msg->override_deploy_policy() >> / C<< $msg->override_deploy_policy($value) >>

Type: C<String>

Optional. Deploy policies to override. Format is
`projects/{project}/locations/{location}/deployPolicies/{deployPolicy}`.

=item * C<< $msg->starting_phase_id() >> / C<< $msg->starting_phase_id($value) >>

Type: C<String>

Optional. The starting phase ID for the `Rollout`. If empty the `Rollout`
will start at the first phase.

=back

