=head2 Google::Cloud::Deploy::V1::CloudDeploy::TimedPromoteReleaseRule

The `TimedPromoteReleaseRule` will automatically promote a release from the
current target(s) to the specified target(s) on a configured schedule.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->id() >> / C<< $msg->id($value) >>

Type: C<String>

Required. ID of the rule. This ID must be unique in the `Automation`
resource to which this rule belongs. The format is
`[a-z]([a-z0-9-]{0,61}[a-z0-9])?`.

=item * C<< $msg->destination_target_id() >> / C<< $msg->destination_target_id($value) >>

Type: C<String>

Optional. The ID of the stage in the pipeline to which this `Release` is
deploying. If unspecified, default it to the next stage in the promotion
flow. The value of this field could be one of the following:

* The last segment of a target name
* "@next", the next target in the promotion sequence

=item * C<< $msg->schedule() >> / C<< $msg->schedule($value) >>

Type: C<String>

Required. Schedule in crontab format. e.g. "0 9 * * 1" for every Monday at
9am.

=item * C<< $msg->time_zone() >> / C<< $msg->time_zone($value) >>

Type: C<String>

Required. The time zone in IANA format [IANA Time Zone
Database](https://www.iana.org/time-zones) (e.g. America/New_York).

=item * C<< $msg->condition() >> / C<< $msg->condition($value) >>

Type: C<Message> (L<Google::Cloud::Deploy::V1::CloudDeploy::AutomationRuleCondition>)

Output only. Information around the state of the Automation rule.

=item * C<< $msg->destination_phase() >> / C<< $msg->destination_phase($value) >>

Type: C<String>

Optional. The starting phase of the rollout created by this rule. Default
to the first phase.

=back

=head2 Google::Cloud::Deploy::V1::CloudDeploy::PromoteReleaseRule

The `PromoteRelease` rule will automatically promote a release from the
current target to a specified target.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->id() >> / C<< $msg->id($value) >>

Type: C<String>

Required. ID of the rule. This id must be unique in the `Automation`
resource to which this rule belongs. The format is
`[a-z]([a-z0-9-]{0,61}[a-z0-9])?`.

