=head2 Google::Cloud::Deploy::V1::CloudDeploy::RepairRolloutRule

The `RepairRolloutRule` automation rule will automatically repair a failed
`Rollout`.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->id() >> / C<< $msg->id($value) >>

Type: C<String>

Required. ID of the rule. This id must be unique in the `Automation`
resource to which this rule belongs. The format is
`[a-z]([a-z0-9-]{0,61}[a-z0-9])?`.

=item * C<< $msg->phases() >> / C<< $msg->phases($value) >>

Type: C<String>

Optional. Phases within which jobs are subject to automatic repair actions
on failure. Proceeds only after phase name matched any one in the list, or
for all phases if unspecified. This value must consist of lower-case
letters, numbers, and hyphens, start with a letter and end with a letter or
a number, and have a max length of 63 characters. In other words, it must
match the following regex: `^[a-z]([a-z0-9-]{0,61}[a-z0-9])?$`.

=item * C<< $msg->jobs() >> / C<< $msg->jobs($value) >>

Type: C<String>

Optional. Jobs to repair. Proceeds only after job name matched any one in
the list, or for all jobs if unspecified or empty. The phase that includes
the job must match the phase ID specified in `source_phase`. This value
must consist of lower-case letters, numbers, and hyphens, start with a
letter and end with a letter or a number, and have a max length of 63
characters. In other words, it must match the following regex:
`^[a-z]([a-z0-9-]{0,61}[a-z0-9])?$`.

=item * C<< $msg->condition() >> / C<< $msg->condition($value) >>

Type: C<Message> (L<Google::Cloud::Deploy::V1::CloudDeploy::AutomationRuleCondition>)

